import "@flux-ui/tokens/theme.css";
import "@flux-ui/tokens/reset.css";
import { Container, Stack } from "@flux-ui/react";
import { createRoot } from "react-dom/client";
import Scene from "./showcase/scenes/commerce-ops.preview.js";
function App() {
  return <Container as="main" size="full" query><Stack gap="lg" padding="md"><Scene /></Stack></Container>;
}
const root = document.getElementById("root");
if (root === null) throw new Error("Missing application root.");
createRoot(root).render(<App />);

